mapper.select:



        AND trigger_type = #{triggerType}


        AND status = #{status}


        AND start_time >= cast(#{params.beginTime} as date)


        AND start_time < cast(#{params.endTime} as date) + interval '1 day'


order by build_id desc

select x.program_id, x.source_url from ( select f.record_id as program_id, f.source_url from abr_field_source f where f.table_name = 'abr_program' and f.record_id in
#{id}
union select r.program_id, f.source_url from abr_field_source f join abr_requirement r on r.requirement_id = f.record_id where f.table_name = 'abr_requirement' and f.record_id in
#{id}
) x where x.source_url is not null and x.source_url <> '' order by x.program_id, x.source_url
